// =============================================================================
// ForgeKV Stage 18 — Benchmark result types
//
// These types match the JSON schema produced by:
//   ./build/forgekv_benchmark --json-output benchmark-results.json
//
// The benchmark result file is a static artifact generated by the developer.
// It is NOT produced by the production server, and it is NOT live data.
// The frontend loads it from /benchmark-results.json (served from public/).
//
// Schema version: 1
// =============================================================================

// ---------------------------------------------------------------------------
// Single workload measurement
// ---------------------------------------------------------------------------
export interface BenchWorkload {
  /** Human-readable workload name, e.g. "Sequential SET" */
  name: string;

  /** Thread count used for this workload (1 = single-threaded) */
  threads: number;

  /** Number of operations performed in the measured phase */
  ops: number;

  /** Wall-clock seconds for the measured phase */
  elapsed_s: number;

  /** Throughput: ops / elapsed_s. 0 for non-throughput workloads (snapshot, compaction). */
  ops_per_sec: number;

  /** Per-operation latency in MICROSECONDS. All fields are 0 if not measured. */
  latency_us: {
    avg: number;
    p50: number;
    p95: number;
    p99: number;
  };

  /** WAL file size in bytes before the workload started. 0 if not applicable. */
  wal_before_bytes: number;

  /** WAL file size in bytes after the workload finished. 0 if not applicable. */
  wal_after_bytes: number;
}

// ---------------------------------------------------------------------------
// Environment info captured at benchmark run time
// ---------------------------------------------------------------------------
export interface BenchEnvironment {
  os: string;
  compiler: string;
  cpp_standard: string;
  hw_threads: number;
}

// ---------------------------------------------------------------------------
// Benchmark configuration used for the run
// ---------------------------------------------------------------------------
export interface BenchConfig {
  operations: number;
  warmup: number;
  value_size_bytes: number;
  max_threads: number;
  latency_enabled: boolean;
  http_enabled: boolean;
}

// ---------------------------------------------------------------------------
// Top-level benchmark result document
// ---------------------------------------------------------------------------
export interface BenchmarkResults {
  schema_version: number;
  forgekv_version: string;
  /** ISO-8601 UTC timestamp when the benchmarks were run */
  generated_at: string;
  environment: BenchEnvironment;
  config: BenchConfig;
  workloads: BenchWorkload[];
}

// ---------------------------------------------------------------------------
// Load state for the benchmark artifact
// ---------------------------------------------------------------------------
export type BenchLoadState =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "ready"; data: BenchmarkResults }
  | { status: "unavailable"; reason: string };
